function restorePolicyParent(){
 if(!policyParent)return;
 if(location.pathname+location.search===policyParent.url){const parent=policyParent,placeholder=document.getElementById(parent.form.id);if(placeholder){policyParent=null;placeholder.replaceWith(parent.form)}else{const retained=document.createElement('section');retained.className='card';retained.dataset.unappliedPolicyDraft='';retained.innerHTML='<h2>Unapplied device draft</h2><p>This device can no longer accept this assignment. The unsaved fields remain here for review.</p>';for(const field of parent.form.elements)field.disabled=true;for(const button of parent.form.querySelectorAll('button'))button.hidden=true;retained.append(parent.form);app.append(retained)}}
 else if(location.pathname!=='/policies')policyParent=null;
}
function returnFromPolicy(value,accepted,reviewedTargets){
 if(!policyParent)return false;
 if(value){
  const form=policyParent.form,policies=JSON.parse(form.dataset.policies).filter(p=>p.id!==value.id),targets=JSON.parse(form.dataset.targets),selected=[...form.querySelectorAll('[name=policy_id]:checked')].map(e=>e.value),sameService=policies.filter(p=>p.service_id===value.service_id).map(p=>p.id);
  policies.push(value);policies.sort((a,b)=>a.id<b.id?-1:a.id>b.id?1:0);
  for(const [kind,id]of [['policy',value.id],['service',value.service_id]]){const target=list(kind==='policy'?accepted.snapshot.targets:reviewedTargets).find(t=>t.target_kind===kind&&t.target_id===id);if(!target||target.deleted||target.conflicted||kind==='policy'&&(target.material_ids.length!==1||target.material_ids[0]!==accepted.material_id))throw Error('Policy saved, but its current rules are unavailable or changed. Review it before assigning.');const index=targets.findIndex(t=>t.target_kind===kind&&t.target_id===id);if(index<0)targets.push(target);else targets[index]=target}
  form.dataset.policies=JSON.stringify(policies);form.dataset.targets=JSON.stringify(targets);
  form.querySelector('[data-policy-choices]').innerHTML=policyChoices([...selected.filter(id=>!sameService.includes(id)),value.id],policies);
  const access=!!form.querySelector('[name=responsibility][value=access]:checked');for(const choice of form.querySelectorAll('[name=policy_id]'))choice.disabled=!access;
  form.querySelector('[role=alert]').textContent='Policy saved. Review and submit this device assignment separately.';
 }
 history.pushState({},'',policyParent.url);render();return true;
}

