function topology(compact=false){const devices=list(projection.devices),view={Nodes:devices.map(device=>({ID:device.id,Name:device.name,Roles:device.roles,Direction:device.direction||'',Health:device.availability,Location:device.location||'',Control:list(device.roles).includes('control')})),SelectedLink:compact?'':new URLSearchParams(location.search).get('link')||'',Links:list(projection.links).map(link=>({ID:link.id,Metrics:[...linkRoundTripMetrics(projection,link,histories.get('link:'+link.id),evidenceNow()).map(v=>v.text),...trafficRates(trafficScope('link:'+link.id),evidenceNow()).map(v=>v.text)],From:link.from,To:link.to,Transport:link.transport,Kind:'tunnel',State:validState(link.availability)}))},routes=list(projection.paths).filter(currentSelection).map(path=>({Chain:[path.device,...list(path.chain)]}));return topologyHTML(view,routes,compact?'overview-topology':'network')}

const byteSize=trafficBytes;
const age=value=>{if(!value)return'—';const seconds=Math.max(0,Math.floor((Date.now()-new Date(value).getTime())/1000));if(seconds<60)return`${seconds}s`;if(seconds<3600)return`${Math.floor(seconds/60)}m`;if(seconds<86400)return`${Math.floor(seconds/3600)}h`;return`${Math.floor(seconds/86400)}d`};
function latestReport(device){return list(reports).filter(v=>v.device_id===device).sort((a,b)=>String(b.reported_at).localeCompare(String(a.reported_at)))[0]}
