 return `<p>${esc(value.platform)} / ${esc(value.architecture)} · ${esc(coordinates)}</p>${mismatch}${existing}<p>${value.can_install?'Verified installation conditions passed.':`Installation unavailable: ${esc(sshReason(value.error_code))}`}</p>`;
