 try{const result=await api('/api/control/ui/ssh/check',{method:'POST',headers:{'Content-Type':'application/json'},body:key});if(canonical(sshDraft(form))!==key){output.textContent='Target or responsibilities changed. Check the target again.';return}form.sshCheck={key,result};output.innerHTML=sshInspectionHTML(result)}catch(error){output.textContent=sshReason(error.message.trim())}finally{button.disabled=false}
