// Keep whole QR modules intact when the delivery card or viewport changes.
// The PNG endpoint emits five source pixels per module, including its quiet zone.
function sizeInviteQR(frame){
 const image=frame.querySelector('img.qr'),note=frame.querySelector('.qr-size-note');if(!image?.naturalWidth)return;
 const modules=image.naturalWidth/5,scale=Math.min(5,Math.floor(frame.clientWidth/modules)),fits=scale>=2;
 image.style.display=fits?'block':'none';if(fits)image.style.width=(modules*scale)+'px';note.hidden=fits;
}
const inviteQRObserver=new ResizeObserver(entries=>{for(const entry of entries)sizeInviteQR(entry.target)});
document.addEventListener('load',event=>{if(event.target.matches?.('img.qr'))sizeInviteQR(event.target.closest('.qr-frame'))},true);
function observeInviteQR(){inviteQRObserver.disconnect();for(const frame of document.querySelectorAll('.qr-frame')){inviteQRObserver.observe(frame);sizeInviteQR(frame)}}
function inviteProjectionKey(device){return canonical({enrollment:device.enrollment||'',facts:targetDependencies(projection.targets,'invite',device.enrollment_id)})}
function deviceInvite(device){
 const id=device.enrollment_id;if(!id)return '';
 const key=inviteProjectionKey(device),cached=inviteCache.get(id),value=cached?.key===key?cached.value:null;
 if(!value){
  if(!inviteLoads.has(id)){
   inviteLoads.add(id);
   api('/api/control/ui/invites/'+encodeURIComponent(id)).then(result=>{
    const current=list(projection.devices).find(v=>v.id===device.id);
    if(current?.enrollment_id===id&&inviteProjectionKey(current)===key)inviteCache.set(id,{key,value:result});
    inviteLoads.delete(id);
    if(location.pathname==='/devices/'+encodeURIComponent(device.id)||location.pathname==='/devices/invites/'+encodeURIComponent(id))stableRender();
   }).catch(error=>{inviteLoads.delete(id);toast(error.message,true)});
  }
  return `<section class="card" id="device-enrollment"><h2>Invitation and joining</h2><p data-enrollment-state>${esc(device.enrollment||'unknown')}</p><p class="dim">Loading authenticated transaction…</p><button data-invite-refresh="${esc(id)}">Refresh transaction</button>${invitationTermination(value)}</section>`;
 }
 return inviteDetails(value);
}
function inviteDetails(value){
 const transaction=value.transaction,id=transaction.id,delivery=value.state==='open'&&value.invite&&Date.now()<value.expires_at;
 return `<section id="device-enrollment"><div class="sectionhead"><h2>Invitation and joining</h2><span class="badge" data-enrollment-state>${esc(value.state)}</span></div><p class="dim">Joining and runtime observation are separate.</p>${value.identity_conflicted?'<p class="note">Conflicting enrollment identities have paused device access. A bound control invitation needs a member majority to cancel.</p>':''}<div class="grid"><section class="card"><h3>${esc(transaction.name||transaction.device_id)}</h3><dl class="device-facts"><dt>Device ID</dt><dd class="mono">${esc(transaction.device_id)}</dd><dt>Requested responsibilities</dt><dd>${esc(transaction.responsibilities.join(' + '))}</dd><dt>Policies</dt><dd>${esc(transaction.policy_ids.join(', ')||'None')}</dd><dt>Delivery</dt><dd>${esc(transaction.medium)}</dd><dt>Expires</dt><dd>${esc(when(value.expires_at))}</dd></dl><button data-invite-refresh="${esc(id)}">Refresh transaction</button>${invitationTermination(value)}</section><section class="card ${transaction.medium==='qr'?'qr-delivery':''}">${transaction.medium==='ssh'?sshDelivery(value):delivery?`${transaction.medium==='qr'?(value.qr_available?`<div class="qr-frame"><img class="qr" src="/api/control/ui/invites/${encodeURIComponent(id)}/qr.png" alt="One-time enrollment QR"><p class="note qr-size-note" hidden>Open the full-size QR to scan, or copy or download the complete invitation.</p><a class="button" href="/api/control/ui/invites/${encodeURIComponent(id)}/qr.png" target="_blank" rel="noopener">Open full-size QR</a></div>`:`<p class="note" role="status">${esc(value.delivery_error||'The invitation cannot be displayed as a QR code. Copy or download the complete invitation.')}</p>`):''}<div class="field"><label>Signed invitation</label><input id="invite-uri" readonly value="${esc(value.invite)}"></div><button data-copy-invite>Copy invite</button><a class="button" href="/api/control/ui/invites/${encodeURIComponent(id)}/download" download>Download invite</a>${transaction.medium==='sh'?(value.shell_command?`<div class="field"><label for="invite-command">Install command</label><textarea id="invite-command" class="mono" readonly rows="16">${esc(value.shell_command)}</textarea></div><button class="primary" data-copy-install-command>Copy command</button><p class="note">Paste the complete block into a root shell on the target Linux machine. It contains the invitation and may remain in terminal history or session recordings.</p>`:`<p class="note" role="status">${esc(value.delivery_error||'A verified public installer is unavailable.')}</p>`):''}`:'<p class="dim">This transaction cannot issue another fresh invitation.</p>'}</section></div></section>`;
}
function invitePage(id){
 const device=list(projection.devices).find(v=>v.enrollment_id===id);
 app.className='network-page page-enrollment';
 if(device){app.innerHTML=heading('Device invitation',esc(device.name||device.id))+deviceInvite(device)+`<div class="actions"><a class="button primary" href="/devices/${encodeURIComponent(device.id)}" data-nav>Continue in device details</a></div>`;return}
 // A terminated transaction remains addressable after its unbound DeviceID is
 // reused. Facts invalidate this disposable cache; report updates do not.
 const key=canonical(list(projection.targets)),cached=inviteCache.get(id),value=cached?.key===key?cached.value:null;
 if(value){app.innerHTML=heading('Device invitation',esc(value.transaction.name||value.transaction.device_id))+inviteDetails(value)+'<div class="actions"><a class="button" href="/devices" data-nav>Back to nodes</a></div>';return}
 app.innerHTML=heading('Device invitation','Loading authenticated transaction…');
 if(inviteLoads.has(id))return;
 inviteLoads.add(id);
 api('/api/control/ui/invites/'+encodeURIComponent(id)).then(result=>{
  if(canonical(list(projection.targets))===key)inviteCache.set(id,{key,value:result});
  inviteLoads.delete(id);
  if(location.pathname==='/devices/invites/'+encodeURIComponent(id))stableRender();
 }).catch(error=>{
  inviteLoads.delete(id);
  if(location.pathname==='/devices/invites/'+encodeURIComponent(id))app.innerHTML=heading('Invitation unavailable',esc(error.message))+`<button data-invite-refresh="${esc(id)}">Retry</button>`;
 });
}
function devicePage(id){
  const device=list(projection.devices).find(v=>v.id===id);if(!device){app.innerHTML=heading('Device not found','The certified projection has no such identity.');return}
  const paths=list(projection.paths).filter(v=>v.device===id),report=latestReport(id),traffic=trafficFor(id),components=componentRows(device,report);
  const pathRows=paths.map(v=>`<tr><td>${esc(v.candidate_id)}</td><td class="mono">${esc(pathLabel(v))}</td><td>${currentSelection(v)?'<span class="ok">current selector</span>':v.selected?'Historical selector':'—'}</td><td>${badge(v.availability)}</td></tr>`).join('');
  const linkRows=list(report?.links).map(v=>`<tr><td class="mono">${esc(v.interface)}</td><td>${esc(v.peer)}</td><td>${badge(v.result)}</td><td>${v.latency_ms?`${esc(v.latency_ms)} ms`:'—'}</td><td>${byteSize(v.rx_bytes)}</td><td>${byteSize(v.tx_bytes)}</td></tr>`).join('');
  const measurementRows=list(report?.observations).map(v=>`<tr data-observation-link="${esc(v.link_id)}"><td>${esc(v.action)}<small class="mono">${esc(v.link_id||v.service_id||v.resource_id)}</small></td><td class="mono">${esc(v.target)}</td><td>${badge(v.current_until>evidenceNow()?v.result:'unknown')}<small>Reported result: ${esc(v.result)}</small><small>Sample: ${esc(when(v.observed_at))}</small><small>${v.current_until>evidenceNow()?'Current sample':v.observed_at>evidenceNow()?'Future sample time':evidenceNow()>=v.valid_until?'Expired sample':'Current validity unconfirmed'}</small></td><td>${esc(v.duration_ms!=null?`${v.duration_ms} ms`:'—')}${v.round_trip_ms!=null?`<small>WG DNS RTT: ${esc(v.round_trip_ms)} ms (reported)</small>`:''}<small>${v.action==='hysteria2_tls'?'Complete Hy2 authentication':v.action==='wireguard_dns'?'Complete WG DNS probe':'Complete HTTPS request'}</small></td></tr>`).join('');
  const runtime=report?.runtime?{...report.runtime,state:device.runtime_state}:null,agent=list(report?.components).find(v=>v.component_id==='agent');
  app.className='network-page page-device';
  app.innerHTML=`<div class="heading network-heading device-heading"><div><span class="eyebrow">NODES / DETAIL</span><h1>${esc(device.name||device.id)}</h1><p>${esc([device.location,list(device.roles).join(' + '),device.direction,device.endpoint].filter(Boolean).join(' · ')||device.id)}</p></div><div class="actions"><a href="/devices" data-nav>Nodes</a><span class="dim">/</span><a href="/topology" data-nav>View in topology →</a></div></div><div class="overview-health"><span class="status-check ${device.availability==='available'?'':'warn'}">${device.availability==='available'?'✓':'!'}</span><b>${device.availability==='available'?'Current signed evidence is available':`Current availability is ${device.availability||'unknown'}`}</b><span class="dim">${device.authorized?'Authorized':'Not authorized'} · egress capable: ${device.egress_capable?'yes':'no'}</span></div>${deviceInvite(device)}<div class="steps device-status five"><div class="step"><span class="label">Applied view</span><b class="mono">${esc(short(runtime?.applied_view_digest))}</b></div><div class="step"><span class="label">Agent version</span><b class="mono">${esc(agent?.version||'Unknown')}</b></div><div class="step"><span class="label">Runtime</span><b>${esc(runtime?.state||'unknown')}</b></div><div class="step"><span class="label">Components</span><b>${list(report?.components).length} reported</b></div><div class="step"><span class="label">Reported</span><b>${esc(report?when(report.reported_at):'Unknown')}</b></div></div><div class="device-detail-columns"><section class="card" id="device-runtime"><div class="sectionhead"><h2>Runtime</h2><span class="tiny dim" data-report-freshness>${reportIsCurrent(report,evidenceNow())?'Current signed execution readback':'Historical signed execution readback'}</span></div><dl class="device-facts"><dt>State</dt><dd data-runtime-state>${esc(runtime?.state||'unknown')}</dd><dt>Applied view</dt><dd class="mono">${esc(runtime?.applied_view_digest||'—')}</dd><dt>Error code</dt><dd>${esc(runtime?runtime.error_code||'None reported':'Unknown')}</dd></dl><div class="runtime-history-detail">${runtimeHistoryHTML(projection,device,histories.get('runtime:'+device.id))}</div><h3>Reported components</h3>${device.component_error?`<p class="bad">${esc(device.component_error)}</p>`:''}${table(['Component / platform','Expected','Reported','Comparison'],components)}</section><section class="card"><div class="sectionhead"><h2>Observation</h2><span>${badge(device.availability)}</span></div><dl class="device-facts"><dt>Signed report</dt><dd>${esc(report?when(report.reported_at):'No current report')}</dd><dt>Presence</dt><dd>${esc(device.presence||'unknown')}</dd><dt>Platform</dt><dd>${esc(device.platform||'—')}</dd><dt>Role</dt><dd>${esc(list(device.roles).join(' + ')||'—')}</dd><dt>Endpoint</dt><dd class="mono">${esc(device.endpoint||'—')}</dd><dt>View digest</dt><dd class="mono">${esc(device.view_digest||runtime?.applied_view_digest||'—')}</dd></dl><h3>WireGuard interface I/O</h3>${table(['Interface','Peer','State','Latency','RX total','TX total'],linkRows)}</section></div><section class="card device-traffic"><div class="sectionhead"><h2>Forwarding traffic · last 24h</h2><span class="tiny ok">trusted adjacent counter deltas</span></div><div class="traffic-detail"><div><span class="label">HISTORICAL RX</span><div class="metric">${byteSize(traffic.rx)}</div></div><div><span class="label">HISTORICAL TX</span><div class="metric">${byteSize(traffic.tx)}</div></div><div><span class="label">BUCKETS WITH SAMPLES</span><div class="metric">${traffic.covered}</div></div>${trafficBars(traffic,true)}</div><p class="tiny dim">Reset, counter decrease, epoch change and gaps over three minutes are omitted, never treated as zero.</p></section><div class="device-detail-columns"><section class="card"><div class="sectionhead"><h2>Automatic Agent decisions</h2><span class="tiny dim">Read-only · signed device selections</span></div>${table(['Candidate','Agent-selected path','Evidence','Status'],pathRows)}</section><section class="card" id="device-measurements"><h2>Measurements</h2><p class="tiny dim">Original reported samples. Resource/Link authentication and Service requests are separate; samples do not establish current availability.</p>${table(['Type','Target','Observation','Metric'],measurementRows)}</section></div>`
}
function topologyPage(){
  const devices=list(projection.devices),links=list(projection.links),paths=list(projection.paths),observed=links.filter(v=>v.availability!=='unknown').length,selected=paths.filter(currentSelection).length,selectedLink=links.find(v=>v.id===new URLSearchParams(location.search).get('link')),traffic=selectedLink?trafficScope('link:'+selectedLink.id):null;
  const rows=links.map(v=>{const usage=trafficScope('link:'+v.id),reported=devices.find(d=>d.id===v.from)?.last_report_at||'';return `<tr data-link-row="${esc(v.id)}" ${selectedLink?.id===v.id?'class="selected-link"':''}><td><a class="mono" href="/topology?link=${encodeURIComponent(v.id)}" data-nav>${esc(v.from)} → ${esc(v.to)}</a><small>${esc(v.id)} · ${esc(v.transport)}</small></td><td>${badge(v.availability)}${linkRoundTripsHTML(projection,v,histories.get('link:'+v.id),evidenceNow())}<small>Sender report: ${esc(age(reported))}</small>${trafficRatesHTML(usage,evidenceNow())}</td><td>${linkHistoryHTML(projection,v,histories.get('link:'+v.id))}</td><td><span class="link-total">${byteSize(usage.tx)}</span><small>Shared peer · both endpoints TX</small>${trafficBars(usage)}</td></tr>`}).join('');
  app.className='network-page page-topology';
  app.innerHTML=`<div class="network-heading"><span class="eyebrow">NETWORK / TOPOLOGY</span><h1>Network topology</h1><p class="dim">Certified intent, signed observations and read-only automatic decisions</p></div><div class="overview-health"><span class="status-check ${observed===links.length&&links.length?'':'warn'}">${observed===links.length&&links.length?'✓':'!'}</span><b>${devices.length} nodes · ${links.length} persistent links · ${selected} automatic decisions</b><span class="dim">Missing evidence remains unknown.</span></div><div class="topology-layout"><section class="card topology-stage"><div class="topology-card-head"><div><h2>Topology layers</h2><p class="dim">Declared structure remains visible when trusted observation is missing.</p></div><div class="legend"><span><i class="key candidate"></i>persistent link</span><span><i class="key direct-hy2"></i>observed</span><span><i class="key route"></i>automatic · read-only</span></div></div><div id="topology">${topology()}</div><p class="topology-caption">Candidate edges describe allowable paths. A missing observed edge does not prove there is no route.</p></section><aside class="topology-side"><section class="card topology-status-card"><div class="sectionhead"><h2>Layer status</h2><span class="tiny ${observed===links.length?'ok':'dim'}">${observed===links.length?'ALL OBSERVED':'PARTIAL'}</span></div><div class="layer-carriers"><span class="label">PERSISTENT LINKS</span><div class="metric ${observed===links.length?'ok':''}">${observed} / ${links.length} observed</div><p class="tiny dim">certified intent · signed evidence</p></div><div class="topology-status-grid"><div><span class="label">AVAILABLE</span><div class="metric">${links.filter(v=>v.availability==='available').length}</div></div><div><span class="label">UNKNOWN</span><div class="metric">${links.filter(v=>v.availability==='unknown').length}</div></div></div><div class="layer-routing"><span class="label">AUTOMATIC ROUTING</span><p>${selected} signed selector readbacks</p><a href="/routing" data-nav>Inspect live paths →</a></div></section><section class="card topology-traffic-card" data-selected-link="${esc(selectedLink?.id||'')}"><div class="sectionhead"><h2>Selected link traffic</h2><span class="tiny">shared WG peer</span></div>${traffic?`<p><b>${esc(selectedLink.id)}</b><br>${esc(selectedLink.from)} → ${esc(selectedLink.to)}</p><div class="link-traffic-body"><div><span class="label">24H ENDPOINT TX</span><div class="metric">${byteSize(traffic.forward)}</div><span class="tiny dim">${traffic.covered} hours with observed deltas</span></div>${trafficBars(traffic,false,false,true)}</div>${linkRoundTripsHTML(projection,selectedLink,histories.get('link:'+selectedLink.id),evidenceNow())}${trafficRatesHTML(traffic,evidenceNow())}<p class="tiny dim">Both endpoint TX series use the same scale. Shared peer bytes include WG overhead; they are not exclusive to this direction or Service.</p>`:'<p class="dim">Select a link on the diagram or in the table to inspect both endpoint TX series.</p>'}</section></aside></div><section class="card topology-edge-card"><div class="edge-panel-head"><h2>Persistent links</h2><span class="dim">24h values use only valid same-epoch adjacent samples.</span></div>${table(['LINK / DIRECTION','CURRENT OBSERVATION','STATE HISTORY','TRANSFER HISTORY'],rows)}</section>`
}
let routingHistory=null,routingHistoryLoad=null;
function routingPage(){
 app.className='network-page page-routing';
 app.innerHTML=routingHTML(projection,new URLSearchParams(location.search),evidenceNow(),routingHistory,histories);
 queueMicrotask(loadRoutingHistory);
}
async function loadRoutingHistory(){
 if(location.pathname!=='/routing')return;
 const request=routingHistoryRequest(projection,new URLSearchParams(location.search));
 if(!request||routingHistory?.key===request.key||routingHistoryLoad===request.key)return;
 routingHistoryLoad=request.key;
 const current=()=>location.pathname==='/routing'&&routingHistoryRequest(projection,new URLSearchParams(location.search))?.key===request.key;
 try{const data=await api(request.url);if(current()){routingHistory={key:request.key,data};stableRender()}}
 catch(error){if(current()){routingHistory={key:request.key,error:error.message};stableRender()}}
 finally{if(routingHistoryLoad===request.key)routingHistoryLoad=null}
}
function lanState(service){return !service.local_network?.enabled?'Disabled':list(projection.local_network_conflicts).includes(service.id)?'Address conflict · routing stopped':'Enabled · business reachability unconfirmed'}
function lanServiceFields(value,creating,gateway){
 const mapping=value.local_network||{gateway_node_id:gateway||'',local_prefix:'',virtual_prefix:'',enabled:true,allocation_attempt:0},gateways=list(projection.devices).filter(d=>d.authorized&&list(d.roles).includes('forward'));
 if(mapping.gateway_node_id&&!gateways.some(d=>d.id===mapping.gateway_node_id))gateways.push({id:mapping.gateway_node_id,name:mapping.gateway_node_id+' · unavailable'});
 return `<section data-lan-fields ${value.kind==='local_network'?'':'hidden'}><div class="field"><label>Fixed LAN gateway</label><select name="gateway_node_id"><option value="">Select a forward node</option>${gateways.map(d=>`<option value="${esc(d.id)}" ${d.id===mapping.gateway_node_id?'selected':''}>${esc(d.name||d.id)}</option>`).join('')}</select></div><div class="field"><label>Reported local network</label><select name="local_prefix" data-original-prefix="${esc(mapping.local_prefix)}"></select><small data-lan-report></small></div><label class="choice"><input type="checkbox" name="lan_enabled" ${mapping.enabled?'checked':''}>Enable this LAN Service</label><div class="field"><label>Virtual → local address mapping</label><output data-lan-mapping>${esc(mapping.virtual_prefix?mapping.virtual_prefix+' → '+mapping.local_prefix:'Choose a gateway and network, then allocate a virtual prefix.')}</output><small data-lan-state>${creating?'':esc(lanState(value))}</small></div><button type="button" data-lan-allocate>${creating?'Allocate virtual prefix':'Review a new allocation'}</button><p class="dim">Only assigned devices may initiate access through this fixed gateway. The gateway does not become an Internet exit.</p></section>`;
}
function updateLANForm(form,changed=''){
 const lan=form.elements.kind.value==='local_network',original=JSON.parse(form.dataset.service||'{}');
 form.querySelector('[data-internet-fields]').hidden=lan;form.elements.matchers.required=!lan;
 form.querySelector('[data-lan-fields]').hidden=!lan;
 if(changed==='gateway_node_id'||!form.elements.local_prefix.options.length){
  const gateway=form.elements.gateway_node_id.value,device=list(projection.devices).find(d=>d.id===gateway),values=list(device?.evidence?.local_networks).filter(v=>v.lan).map(v=>v.prefix),retained=original.local_network?.gateway_node_id===gateway?original.local_network.local_prefix:'';
  form.elements.local_prefix.innerHTML='<option value="">Select a reported prefix</option>'+values.map(v=>`<option value="${esc(v)}" ${v===retained?'selected':''}>${esc(v)}</option>`).join('')+(retained&&!values.includes(retained)?`<option selected value="${esc(retained)}">${esc(retained)} · not in current report</option>`:'');
  form.querySelector('[data-lan-report]').textContent=device?.evidence?.local_networks?`Reported ${when(device.evidence.reported_at)}. This is interface readback; business availability remains unknown.`:'No current-view LAN report is available.';
 }
 if(changed&&['id','kind','gateway_node_id','local_prefix','lan_enabled'].includes(changed)){
  form.lanAllocation=null;
  form.querySelector('[data-lan-mapping]').textContent=original.local_network?original.local_network.virtual_prefix+' → '+original.local_network.local_prefix:'No allocation reviewed yet.';
 }
}
async function allocateLAN(form){
 const output=form.querySelector('[role=alert]'),button=form.querySelector('[data-lan-allocate]');button.disabled=true;output.textContent='Reading gateway report and address allocation…';
 try{
  const request={schema:3,request_id:form.dataset.requestId,id:form.elements.id.value,name:form.elements.name.value,gateway_node_id:form.elements.gateway_node_id.value,local_prefix:form.elements.local_prefix.value,allocation_attempt:0};
  const operation=await api('/api/control/services/local-network-allocation',{method:'POST',headers:{'Content-Type':'application/json'},body:canonical(request)});
  form.lanAllocation=operation;form.elements.lan_enabled.checked=true;
  form.querySelector('[data-lan-mapping]').textContent=operation.payload.local_network.virtual_prefix+' → '+operation.payload.local_network.local_prefix;
  form.querySelector('[data-lan-state]').textContent='Reviewed allocation · not saved';output.textContent='Review the mapping, then save the Service.';
 }catch(error){output.textContent=error.message}finally{button.disabled=false}
}
function appendDeviceLAN(id){
 const device=list(projection.devices).find(d=>d.id===id),services=list(projection.services).filter(s=>s.local_network?.gateway_node_id===id);
 if(!device||!services.length&&!list(device.roles).includes('forward'))return;
 const report=latestReport(id),prefixes=list(report?.local_networks).filter(v=>v.lan).map(v=>v.prefix);
 app.insertAdjacentHTML('beforeend',`<section class="card" data-device-lan><div class="sectionhead"><h2>Shared LAN Services</h2>${device.authorized&&list(device.roles).includes('forward')&&canOperate('service.put')?`<a class="button" href="/services?new=1&kind=local_network&gateway=${encodeURIComponent(id)}" data-nav>Add LAN Service</a>`:''}</div><p>${prefixes.length?`Reported networks: ${esc(prefixes.join(', '))} · ${esc(when(report.reported_at))}`:'No connected LAN prefix in the current device report.'}</p>${services.map(v=>`<p><a href="/services?service=${encodeURIComponent(v.id)}" data-nav>${esc(v.name||v.id)}</a> · ${esc(v.local_network.virtual_prefix)} → ${esc(v.local_network.local_prefix)}<small>${esc(lanState(v))}</small></p>`).join('')||'<p class="empty">No LAN Service uses this gateway.</p>'}</section>`);
}
function servicesPage(){
 if(new URLSearchParams(location.search).get('tab')==='dns'){dnsPage();return}
 const all=list(projection.services),params=new URLSearchParams(location.search),creating=params.get('new')==='1',value=creating?{id:'',name:'',kind:params.get('kind')==='local_network'?'local_network':'internet',matchers:[]}:all.find(v=>v.id===params.get('service'))||all[0];
 app.className='network-page page-services';
 const catalog=all.map(v=>`<a class="service-item ${v.id===value?.id?'selected':''}" href="/services?service=${encodeURIComponent(v.id)}" data-nav><b>${esc(v.name||v.id)}</b><small>${v.kind==='local_network'?`LAN · ${esc(v.local_network.virtual_prefix)}`:`Internet · ${list(v.matchers).length} rules`}</small></a>`).join('');
 const related=list(projection.policies).filter(v=>v.service_id===value?.id);
 const editor=value?`<section class="service-editor"><h2>${creating?'New Service':esc(value.name)}</h2>${!creating?policyImpact(related.map(p=>p.id)):''}<form id="service-form" data-service="${esc(JSON.stringify(value))}" ${draftAttributes()}><div class="service-identity"><div class="field"><label>SERVICE ID</label><input name="id" required value="${esc(value.id)}" ${value.id?'readonly':''}></div><div class="field"><label>DISPLAY NAME</label><input name="name" required value="${esc(value.name)}"></div></div><div class="field"><label>Service kind</label><select name="kind" ${creating?'':'disabled'}><option value="internet" ${value.kind==='internet'?'selected':''}>Internet</option><option value="local_network" ${value.kind==='local_network'?'selected':''}>Local network</option></select></div><section data-internet-fields ${value.kind==='local_network'?'hidden':''}><div class="field"><label for="service-matchers">Target rules</label><textarea id="service-matchers" name="matchers" rows="7" ${value.kind==='internet'?'required':''} placeholder="dns_exact demo.example&#10;dns_suffix example&#10;ip_prefix 192.0.2.0/24">${esc(list(value.matchers).map(v=>v.kind+' '+v.value).join('\n'))}</textarea><small>One kind and value per line: dns_exact, dns_suffix or ip_prefix.</small></div></section>${lanServiceFields(value,creating,params.get('gateway'))}<div class="service-save"><span id="operation-status" role="alert"></span><button class="primary" type="submit" ${canOperate('service.put')?'':'disabled'}>Save Service</button>${value.id&&canOperate('service.delete')?`<button type="button" class="danger" data-delete-kind="service" data-delete-id="${esc(value.id)}">Delete</button>`:''}</div></form><h3>Policies for this Service</h3>${value.id&&canOperate('policy.put')?`<a class="button" href="/policies?new=1&service=${encodeURIComponent(value.id)}" data-nav>New Policy for this Service</a>`:''}${related.map(p=>`<p><a href="/policies?policy=${encodeURIComponent(p.id)}" data-nav>${esc(p.name||p.id)}</a> · ${esc(p.action)}</p>`).join('')||'<p class="dim">No Policy selects this Service yet.</p>'}</section>`:'<section class="service-editor"><p class="empty">No Service has been created.</p></section>';
 app.innerHTML=heading('Services','Define the targets that policies can authorize.',canOperate('service.put')?'<a class="button primary" href="/services?new=1" data-nav>＋ Add Service</a>':'')+`<div class="service-tabs"><a class="selected" href="/services" data-nav>Services</a><a href="/services?tab=dns" data-nav>Exact .loom DNS</a><a href="/policies" data-nav>Policies</a></div><div class="services-layout"><aside class="card service-catalog">${catalog||'<p class="empty">No services.</p>'}</aside>${editor}</div>`;
 const form=document.querySelector('#service-form');if(form)updateLANForm(form);
}
function releaseTabs(active){return `<div class="release-tabs" role="tablist">${[['linux','Linux'],['android','Android'],['windows','Windows'],['deployments','Device versions']].map(([id,label])=>`<a role="tab" aria-selected="${active===id}" href="${id==='deployments'?'/deployments':`/releases?platform=${id}`}" data-nav>${label}</a>`).join('')}</div>`}
function releasesPage(){
  const requested=new URLSearchParams(location.search).get('platform'),platform=['linux','android','windows'].includes(requested)?requested:'linux';
  const productPlatform=value=>value==='linux-server'?'linux':value==='windows-desktop'?'windows':value;
  const artifacts=list(projection.releases).filter(value=>productPlatform(value.platform)===platform);
  const companion=(label,file)=>file?.url?`<a class="button" href="${esc(file.url)}" download title="SHA-256 ${esc(file.sha256)}">${label}</a>`:'';
  const card=value=>`<section class="card package" data-key="release:${esc(value.path)}"><div class="package-heading"><span class="platform-mark ${esc(platform)}">${esc(platform.slice(0,1).toUpperCase())}</span><div><h3>${esc(value.title||value.name)}</h3><span class="muted">${esc(value.platform)} · ${esc(value.arch)} · ${esc(value.variant)}</span></div></div><p>${esc(value.version)} · source <span class="mono">${esc(short(value.source_commit))}</span></p><dl class="device-facts"><dt>SHA-256</dt><dd class="mono">${esc(value.sha256)}</dd><dt>Signature</dt><dd>${esc(value.signing||'Unknown')}</dd><dt>Size</dt><dd>${byteSize(value.size)}</dd></dl><div class="actions"><a class="button primary" href="${esc(value.url)}" download>Download exact bytes</a>${companion('Checksum',value.checksum)}${companion('Manifest',value.manifest)}${companion('Signature',value.signature)}${companion('SBOM',value.sbom)}</div></section>`;
  const developer=artifacts.filter(value=>/(debug|developer|nightly|preview)/i.test(`${value.variant||''} ${value.signing||''}`)),stable=artifacts.filter(value=>!developer.includes(value));
  const group=(title,values,empty)=>`<section class="release-group"><div class="sectionhead"><h2>${title}</h2><span class="tiny dim">${values.length} exact artifact${values.length===1?'':'s'}</span></div><div class="grid package-grid">${values.map(card).join('')||`<p class="empty">${empty}</p>`}</div></section>`;
  app.className='network-page page-releases';
  app.innerHTML=heading('Releases','Verified packages remain visible independently from fleet deployment evidence.')+releaseTabs(platform)+group('Stable',stable,`No verified ${esc(platform)} stable release is available.`)+(developer.length?group('Developer / debug',developer,'No developer build is available.'):'');
}
