 const entries=list(projection.web_endpoints),website=entries.length?`<a href="https://control.loom:${entries[0].port}/" target="_blank" rel="noreferrer">Open control.loom</a><small>${entries.map(v=>esc(v.host)+':'+v.port).join(' · ')} · Authenticated entries; reachability unconfirmed</small>`:'No serving website entry with authorized trust and a consistent port.';
 const selected=params.get('record'),creating=params.get('new')==='1';
 const editor=value=>`<form id="dns-record-form" ${draftAttributes()} data-creating="${!value.id}"><div class="service-identity"><div class="field"><label>RECORD ID</label><input name="id" required value="${esc(value.id)}" ${value.id?'readonly':''}></div><div class="field"><label>EXACT PRIVATE NAME</label><input name="name" required value="${esc(value.name)}" placeholder="demo-service.loom"></div></div><div class="field"><label>LAN Service (optional)</label><select name="dns_service_id"><option value="">Independent record</option>${list(projection.services).filter(v=>v.kind==='local_network').map(v=>`<option value="${esc(v.id)}" ${value.service_id===v.id?'selected':''}>${esc(v.name||v.id)} · ${esc(v.local_network.virtual_prefix)}</option>`).join('')}${value.service_id&&!list(projection.services).some(v=>v.id===value.service_id)?`<option selected value="${esc(value.service_id)}">${esc(value.service_id)} · unavailable</option>`:''}</select><small>A LAN record contains virtual addresses from this Service and is withdrawn with its authorization.</small></div><div class="field"><label>Addresses</label><textarea name="addresses" required rows="3" placeholder="192.0.2.10&#10;2001:db8::10">${esc(value.addresses.join('\n'))}</textarea><small>One IPv4 or IPv6 address per line. Resolving a name does not grant access to its service.</small></div><div class="service-save"><span role="alert"></span><button class="primary" type="submit" ${canOperate('dns_record.put')?'':'disabled'}>Save record</button>${value.id&&canOperate('dns_record.delete')?`<button class="danger" type="button" data-delete-kind="dns_record" data-delete-id="${esc(value.id)}">Delete</button>`:''}<a class="button" href="/services?tab=dns" data-nav>Close</a></div></form>`;
