document.addEventListener('submit',async event=>{
 if(event.target.matches('[data-website-form]')){event.preventDefault();await submitWebsiteForm(event.target,{api,operate,refresh:async()=>{await refresh(false);render()},toast,projection});return}
 if(event.target.matches('#member-change-form,#invite-termination-form')){event.preventDefault();await handleMemberForm(event.target);return}

 if(event.target.matches('[data-page-filter]')){event.preventDefault();const query=new URLSearchParams(new FormData(event.target));for(const [key,value]of [...query])if(!value)query.delete(key);history.pushState({},'',`${location.pathname}${query.size?'?'+query:''}`);render();return}
 const element=event.target;if(!element.matches('#dns-record-form,#service-form,#policy-form,#device-policy-form,#expected-component-form,#enrollment-form,#admin-certificate-form,#public-trust-form'))return;
 event.preventDefault();if(element.submitting)return;element.submitting=true;const form=new FormData(element),output=element.querySelector('[role=alert]'),ids=name=>String(form.get(name)||'').split(',').map(v=>v.trim()).filter(Boolean).sort();output.textContent='Submitting…';
 try{
  let operation,payload,dependencies;
  if(element.getAttribute('id')==='public-trust-form'){
   const file=form.get('certificate');if(!(file instanceof File)||!file.size||file.size>65536)throw Error('Select one public PEM root certificate.');
   const raw=(await file.text()).trim(),match=raw.match(/^-----BEGIN CERTIFICATE-----\r?\n([A-Za-z0-9+/=\r\n]+)\r?\n-----END CERTIFICATE-----$/);if(!match)throw Error('Select one public PEM root certificate.');
   const binary=atob(match[1].replace(/\s/g,'')),der=Uint8Array.from(binary,v=>v.charCodeAt(0)),digest=await crypto.subtle.digest('SHA-256',der);
   payload={id:'website-'+[...new Uint8Array(digest)].map(v=>v.toString(16).padStart(2,'0')).join(''),purpose:'website',certificate_der:btoa(binary).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'')};
   operation='public_trust.put';dependencies=commandDependencies(element,'public_trust',payload.id);
  }else if(element.getAttribute('id')==='admin-certificate-form'){
   const file=form.get('certificate');if(!(file instanceof File)||!file.size||file.size>65536)throw Error('Select the public admin.json file.');
   const raw=await file.text();payload=JSON.parse(raw);if(canonical(payload)!==raw||Object.keys(payload).sort().join(',')!=='certificate_der,id'||typeof payload.id!=='string'||typeof payload.certificate_der!=='string')throw Error('Select the original canonical public admin.json file.');
   operation='admin_certificate.put';dependencies=commandDependencies(element,'admin_certificate',payload.id);
  }else if(element.getAttribute('id')==='dns-record-form'){
   operation='dns_record.put';payload={id:String(form.get('id')),name:String(form.get('name')),addresses:String(form.get('addresses')).split('\n').map(v=>v.trim()).filter(Boolean).sort()};
   if(element.dataset.creating==='true'&&JSON.parse(element.dataset.targets).some(t=>t.target_kind==='dns_record'&&t.target_id===payload.id))throw Error('A new record needs an unused ID.');
   const serviceID=String(form.get('dns_service_id')||'');if(serviceID)payload.service_id=serviceID;
   dependencies=commandDependencies(element,'dns_record',payload.id,[],serviceID);
  }else if(element.getAttribute('id')==='service-form'){
   operation='service.put';payload={id:String(form.get('id')),name:String(form.get('name')),kind:element.elements.kind.value};
   if(payload.kind==='internet'){payload.matchers=parseMatchers(form.get('matchers'));dependencies=commandDependencies(element,'service',payload.id)}else{
    const original=JSON.parse(element.dataset.service).local_network,prepared=element.lanAllocation,gateway=String(form.get('gateway_node_id')),prefix=String(form.get('local_prefix')),enabled=form.has('lan_enabled');
    if(prepared&&prepared.payload.id===payload.id&&prepared.payload.local_network.gateway_node_id===gateway&&prepared.payload.local_network.local_prefix===prefix){payload.local_network={...prepared.payload.local_network,enabled};dependencies=prepared.dependencies}
    else if(original&&original.gateway_node_id===gateway&&original.local_prefix===prefix&&(!enabled||original.enabled)){payload.local_network={...original,enabled};dependencies=commandDependencies(element,'service',payload.id,[],undefined,[gateway])}
    else throw Error('Allocate and review a virtual prefix before saving this LAN mapping.');
   }
  }else if(element.getAttribute('id')==='policy-form'){
   const scope=name=>{const mode=String(form.get(name+'_mode'));return {mode,node_ids:mode==='only'?ids(name+'_ids'):[]}};
   operation='policy.put';payload={id:String(form.get('id')),name:String(form.get('name')),service_id:element.elements.namedItem('service_id').value,action:String(form.get('action')),entry_scope:scope('entry_scope'),relay_scope:scope('relay_scope')};
   const service=list(projection.services).find(v=>v.id===payload.service_id);if(!service)throw Error('The reviewed Service is unavailable.');if(service.kind==='internet')Object.assign(payload,{exit_scope:scope('exit_scope'),allow_direct:form.has('allow_direct'),local_egress_devices:ids('local_egress_devices')});
   if(element.dataset.creating==='true'&&JSON.parse(element.dataset.targets).some(t=>t.target_kind==='policy'&&t.target_id===payload.id))throw Error('A new Policy needs an unused ID. The existing Policy was not changed.');
   const maxHops=String(form.get('max_hops')||'').trim();if(maxHops){if(!/^[1-9][0-9]*$/.test(maxHops)||!Number.isSafeInteger(Number(maxHops)))throw new Error('Maximum managed nodes must be a positive integer.');payload.max_hops=Number(maxHops);}
   dependencies=commandDependencies(element,'policy',payload.id,[],payload.service_id,[...payload.entry_scope.node_ids,...payload.relay_scope.node_ids,...list(payload.exit_scope?.node_ids),...list(payload.local_egress_devices)]);
  }else if(element.getAttribute('id')==='expected-component-form'){
   operation='expected_component.put';payload=JSON.parse(String(form.get('component')));payload.id=await expectedComponentID(payload);dependencies=commandDependencies(element,'expected_component',payload.id,[],undefined,[payload.node_id]);
  }else if(element.getAttribute('id')==='device-policy-form'){
   operation='device.put';payload={id:element.dataset.deviceId,name:String(form.get('name')),responsibilities:form.getAll('responsibility').map(String).sort(),policy_ids:form.getAll('policy_id').map(String).sort(),distribution_urls:String(form.get('distribution_urls')).split('\n').map(v=>v.trim()).filter(Boolean).sort()};const dns=String(form.get('dns_servers')||'').split('\n').map(v=>v.trim()).filter(Boolean).sort();if(dns.length)payload.dns_servers=dns;dependencies=commandDependencies(element,'device',payload.id,payload.policy_ids);
  }else{
   const options=JSON.parse(element.dataset.options),endpoint=options.endpoints[Number(form.get('endpoint'))];if(!endpoint)throw Error('No authenticated serving endpoint is available.');
   operation='invite.issue';payload={id:element.dataset.transactionId,genesis_digest:options.genesis_digest,issuer_control_id:options.issuer_control_id,device_id:String(form.get('device_id')),name:String(form.get('name')),responsibilities:form.getAll('responsibility').map(String).sort(),policy_ids:form.getAll('policy_id').map(String).sort(),medium:String(form.get('medium')),endpoint};const dns=String(form.get('dns_servers')||'').split('\n').map(v=>v.trim()).filter(Boolean).sort();if(dns.length)payload.dns_servers=dns;
   if(payload.medium==='ssh'){payload.ssh_target=String(form.get('ssh_target')||'');const checked=element.sshCheck;if(!checked||checked.key!==canonical(sshDraft(element)))throw Error('Check the selected SSH target and responsibilities first.');if(checked.result.installation.identity)throw Error('Manage the existing device or continue its original invitation.');if(!checked.result.installation.can_install)throw Error('The target installation conditions have not passed.');}
   dependencies=commandDependencies(element,'invite',payload.id,payload.policy_ids);dependencies.push(...targetDependencies(JSON.parse(element.dataset.targets),'endpoint',endpoint.id,true));
  }
  // Keep the exact submitted bytes with this disposable draft. A new edit
  // gets a new request ID, while its reviewed object/dependency IDs stay put.
  const draft=canonical({operation,payload,dependencies:[...new Set(dependencies)].sort()});
  if(!element.submission||element.submission.draft!==draft){
   if(element.submission)element.dataset.requestId=crypto.randomUUID();
   if(operation==='invite.issue')payload.expires_at=Date.now()+15*60*1000;
   element.submission={draft,body:operationBody(operation,payload,element.dataset.requestId,dependencies)};
  }
  const accepted=await submitOperation(operation,element.submission.body);
  // A completed request may update readback, but cannot reclaim a page the user left.
  if(element.isConnected){
   if(operation==='service.put')history.pushState({},'',`/services?service=${encodeURIComponent(payload.id)}`);
   if(operation==='dns_record.put')history.pushState({},'',`/services?tab=dns&record=${encodeURIComponent(payload.id)}`);
   if(operation==='policy.put'){if(returnFromPolicy(payload,accepted,JSON.parse(element.dataset.targets))){toast('Policy saved. Device assignment is still a draft.');return}history.pushState({},'',`/policies?policy=${encodeURIComponent(payload.id)}`)}
   if(operation==='invite.issue')history.pushState({},'',`/devices/invites/${encodeURIComponent(payload.id)}`);
   render();
  }else stableRender();
  if(operation==='invite.issue'&&payload.medium==='ssh'){try{await startSSH(payload.id);inviteCache.delete(payload.id);stableRender();toast('Invitation accepted. SSH execution started.')}catch(error){toast('Invitation accepted; SSH execution not confirmed: '+error.message,true)}}else toast('Accepted locally. Device propagation is separate.');
 }catch(error){output.textContent=error.message}finally{element.submitting=false}
});
let reconnectDelay=1000;
function connectLive(){const scheme=location.protocol==='https:'?'wss:':'ws:',socket=new WebSocket(`${scheme}//${location.host}/api/control/ui/live`);socket.onopen=()=>{reconnectDelay=1000;connection.className='ok'};socket.onmessage=event=>{const payload=JSON.parse(event.data),encoded=JSON.stringify(payload);if(encoded!==lastSnapshot){lastSnapshot=encoded;const editing=document.activeElement&&/^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement.tagName);accept(payload,!editing)}};socket.onclose=()=>{connection.textContent='Reconnecting…';connection.className='bad';const delay=reconnectDelay;reconnectDelay=Math.min(30000,reconnectDelay*2);setTimeout(connectLive,delay)};socket.onerror=()=>socket.close()}
const navIcons=['overview','devices','topology','services','services','routing','releases','events','ssot'];document.querySelectorAll('nav a').forEach((link,index)=>link.insertAdjacentHTML('afterbegin',icon(navIcons[index])));
document.addEventListener('focusout',()=>queueMicrotask(()=>{const editing=document.activeElement&&/^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement.tagName);if(deferredRender&&!editing){deferredRender=false;stableRender()}}));
document.addEventListener('keydown',event=>{const tab=event.target.closest?.('.release-tabs [role=tab]');if(!tab||!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;const tabs=[...tab.parentElement.querySelectorAll('[role=tab]')],index=tabs.indexOf(tab);let next=event.key==='Home'?0:event.key==='End'?tabs.length-1:event.key==='ArrowLeft'?(index-1+tabs.length)%tabs.length:(index+1)%tabs.length;event.preventDefault();tabs[next].focus();tabs[next].click()});
Promise.all([refresh(true),loadEnrollmentOptions()]).then(connectLive).catch(error=>{connection.textContent='Unavailable';connection.className='bad';app.innerHTML=`<p class="note error">${esc(error.message)}</p>`;setTimeout(()=>refresh(true).then(connectLive),2000)});

// Process progress can change without a new control fact. Refresh only the visible
// execution projection, leaving device editing drafts intact.
setInterval(()=>{const card=document.querySelector('#device-enrollment'),state=card?.querySelector('[data-ssh-state]')?.textContent;if(state!=='running')return;const id=card.querySelector('[data-invite-refresh]')?.dataset.inviteRefresh;if(id&&!inviteLoads.has(id)){inviteCache.delete(id);stableRender()}},3000);

function memberSection(){
 const members=list(projection.members),can=admin&&projection.capabilities?.member_changes;
 return `<section class="card" id="control-members"><h2>Control members</h2><p>Changes require ${Math.floor(members.length/2)+1} of the ${members.length} current members. A request may remain pending when members cannot be reached.</p>${table(['CONTROL','NODE','SIGNING KEY'],members.map(v=>`<tr data-key="${esc(v.control_id)}"><td>${esc(v.control_id)}</td><td><a href="/devices/${encodeURIComponent(v.node_id)}" data-nav>${esc(v.node_id)}</a></td><td class="mono">${esc(short(v.key_id))}</td></tr>`).join(''))}${can?`<form id="member-change-form" data-request-id="${crypto.randomUUID()}" data-base="${esc(projection.control_config_id)}"><div class="field"><label>Node</label><select name="node">${members.map(v=>`<option value="${esc(v.node_id)}">${esc(v.node_id)}</option>`).join('')}</select></div><div class="field"><label>Change</label><select name="change"><option value="revoke">Revoke control responsibility; keep ordinary responsibilities</option><option value="delete">Delete entire node and its permissions</option><option value="resign">Resign this control</option><option value="rotate">Rotate this control's signing key</option></select></div><div class="field"><label>Prepared public signing key (rotation only)</label><input name="public_key" autocomplete="off"><small>Resign and rotate must be submitted on the owning control (${esc(projection.local_node_id)}). Prepare the new key and transport certificate locally before rotation, then restart this control after certification.</small></div><span role="alert"></span><button type="submit" class="primary">Apply member change</button></form>`:''}<a class="button" href="/devices?new=1" data-nav>Add a node with control responsibility</a></section>`;
}
async function submitMemberChange(request){
 const result=await api('/api/control/members',{method:'POST',headers:{'Content-Type':'application/json'},body:canonical(request)});
 await refresh(false);
 if(!result.requested_change_applied)throw Error(`The member table decided ${result.certificate.config.operation} for ${result.certificate.config.target_node_id}. This request is not complete; review the updated table before retrying.`);
 return result;
}
function invitationTermination(value){
 if(!value||!admin||!['open','bound','completed'].includes(value.state)||value.state==='completed'&&!value.member_enrollment)return '';
 if(value.member_enrollment&&value.state!=='open'&&!projection.capabilities?.member_changes)return '';
 if((!value.member_enrollment||value.state==='open')&&!canOperate('invite.cancel'))return '';
 const action=value.member_enrollment&&value.state==='completed'?'Delete entire joined node':'Cancel invitation';
 return `<form id="invite-termination-form" ${draftAttributes()} data-base="${esc(projection.control_config_id)}" data-transaction="${esc(JSON.stringify({id:value.transaction.id,node:value.transaction.device_id,material:value.material_id,member:value.member_enrollment,state:value.state}))}"><p>${value.member_enrollment&&value.state!=='open'?'Requires the current member majority. A completed join stays in history; terminating it deletes the entire node.':'The original bound identity and signed history are preserved.'}</p><span role="alert"></span><button class="danger" type="submit">${action}</button></form>`;
}
async function handleMemberForm(element){
 if(element.submitting)return;element.submitting=true;const output=element.querySelector('[role=alert]');output.textContent='Requesting the current member decision…';
 try{
  if(element.id==='member-change-form'){
   const data=new FormData(element),operation=String(data.get('change')),target=String(data.get('node'));
   if(['resign','rotate'].includes(operation)&&target!==projection.local_node_id)throw Error('Open the owning control to submit this voluntary change.');
   const request={schema:3,base_config_id:element.dataset.base,operation,target_node_id:target};
   if(operation==='rotate')request.public_key=String(data.get('public_key')).trim();
   await submitMemberChange(request);
   output.textContent=operation==='rotate'?'New signing key certified. Restart this control to activate the prepared identity.':'Member certificate accepted. Other controls apply it when received.';
  }else{
   const transaction=JSON.parse(element.dataset.transaction);
   if(transaction.member&&transaction.state!=='open'){
    const request={schema:3,base_config_id:element.dataset.base,operation:transaction.state==='completed'?'delete':'invalidate_join',target_node_id:transaction.node};
    if(request.operation==='invalidate_join'){request.transaction_id=transaction.id;request.reason='cancelled'}
    await submitMemberChange(request);
   }else{
    const dependencies=[...new Set([...targetDependencies(JSON.parse(element.dataset.targets),'invite',transaction.id),transaction.material])].sort();
    await api('/api/control/operations',{method:'POST',headers:{'Content-Type':'application/json'},body:canonical({schema:3,request_id:element.dataset.requestId,operation:'invite.cancel',target_kind:'invite',target_id:transaction.id,dependencies,payload:{transaction_id:transaction.id,invite_material_id:transaction.material}})});
   }
   inviteCache.delete(transaction.id);output.textContent='Termination accepted. Refresh the transaction to read back its final state.';await refresh(false);
  }
 }catch(error){output.textContent=error.message}finally{element.submitting=false;if(element.dataset.base!==projection.control_config_id){const message=output.textContent;render();const next=document.querySelector('#'+element.id+' [role=alert]');if(next)next.textContent=message;else toast(message)}}
}

